script:
frappe.ui.form.on('Item', {
    refresh: function(frm) {
        // Tek ürün senkronizasyon butonu
        frm.add_custom_button(__('WooCommerce ile Senkronize Et'), function() {
            frappe.confirm(
                'Bu ürünü WooCommerce ile senkronize etmek istediğinize emin misiniz?',
                function() {
                    // Mevcut save işlemini tetikle (handle_item_saved otomatik çalışacak)
                    frappe.call({
                        method: 'frappe.client.save',
                        args: {
                            doc: frm.doc
                        },
                        freeze: true,
                        freeze_message: __('WooCommerce ile senkronize ediliyor...'),
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.show_alert({
                                    message: __('Ürün başarıyla senkronize edildi!'),
                                    indicator: 'green'
                                }, 5);
                                frm.reload_doc();
                            }
                        }
                    });
                }
            );
        }, __('WooCommerce'));
    }
});

frappe.listview_settings['Item'] = frappe.listview_settings['Item'] || {};

frappe.listview_settings['Item'].onload = function(listview) {
    listview.page.add_inner_button(__('Tüm Ürünleri WooCommerce ile Senkronize Et'), function() {
        frappe.confirm(
            'TÜM ürünleri WooCommerce ile senkronize etmek istediğinize emin misiniz? Bu işlem uzun sürebilir.',
            function() {
                frappe.call({
                    method: 'culinary_portal.custom_hooks.create_item.sync_all_items_to_woocommerce',
                    freeze: true,
                    freeze_message: __('Tüm ürünler senkronize ediliyor... Lütfen bekleyin...'),
                    callback: function(r) {
                        if (r.message) {
                            let indicator = 'green';
                            if (r.message.status === 'error') {
                                indicator = 'red';
                            } else if (r.message.status === 'partial') {
                                indicator = 'orange';
                            }

                            frappe.msgprint({
                                title: __('Senkronizasyon Tamamlandı'),
                                indicator: indicator,
                                message: r.message.message
                            });

                            listview.refresh();
                        }
                    },
                    error: function(r) {
                        frappe.msgprint({
                            title: __('Hata'),
                            indicator: 'red',
                            message: __('Senkronizasyon sırasında bir hata oluştu.')
                        });
                    }
                });
            }
        );
    }, __('WooCommerce'));
};
